int main() {
    double p0 = 1000.0;
    double r1 = 0.0414, r2 = 0.0468, r3 = 0.054, r5 = 0.0585, r0 = 0.0072;
    double p1, p2_3, p3_2, p1_5, p0_5;

    // 1. 一次存5年期
    p1 = p0 * (1 + 5 * r5);

    // 2. 先存2年期，再存3年期
    p2_3 = (p0 * (1 + 2 * r2)) * (1 + 3 * r3);

    // 3. 先存3年期，再存2年期
    p3_2 = (p0 * (1 + 3 * r3)) * (1 + 2 * r2);

    // 4. 连续存5次1年期
    p1_5 = p0 * pow(1 + r1, 5);

    // 5. 活期存款，5年共20个季度
    p0_5 = p0 * pow(1 + r0 / 4, 4 * 5);

    printf("方法1本息和: %.2f\n", p1);
    printf("方法2本息和: %.2f\n", p2_3);
    printf("方法3本息和: %.2f\n", p3_2);
    printf("方法4本息和: %.2f\n", p1_5);
    printf("方法5本息和: %.2f\n", p0_5);

    return 0;
}

