#include <stdio.h>

int main() {
    long int num;
    int digit, places = 0;
    int ten_thousands, thousands, hundreds, tens, ones;

    printf("请输入一个不多于5位的正整数: ");
    scanf("%ld", &num);

    if (num > 99999 || num < 0) {
        printf("输入无效\n");
        return 1;
    }

    if (num > 9999) places = 5;
    else if (num > 999) places = 4;
    else if (num > 99) places = 3;
    else if (num > 9) places = 2;
    else places = 1;

    printf("它是 %d 位数\n", places);

    ten_thousands = num / 10000;
    thousands = (num / 1000) % 10;
    hundreds = (num / 100) % 10;
    tens = (num / 10) % 10;
    ones = num % 10;

    printf("每一位数字为: ");
    switch(places) {
        case 5: printf("%d,%d,%d,%d,%d", ten_thousands, thousands, hundreds, tens, ones); break;
        case 4: printf("%d,%d,%d,%d", thousands, hundreds, tens, ones); break;
        case 3: printf("%d,%d,%d", hundreds, tens, ones); break;
        case 2: printf("%d,%d", tens, ones); break;
        case 1: printf("%d", ones); break;
    }
    printf("\n");

    printf("逆序输出为: ");
    switch(places) {
        case 5: printf("%d%d%d%d%d", ones, tens, hundreds, thousands, ten_thousands); break;
        case 4: printf("%d%d%d%d", ones, tens, hundreds, thousands); break;
        case 3: printf("%d%d%d", ones, tens, hundreds); break;
        case 2: printf("%d%d", ones, tens); break;
        case 1: printf("%d", ones); break;
    }
    printf("\n");

    return 0;
}

#include <stdio.h>

int main() {
    int a, b, c, d, t;
    printf("请输入4个整数: ");
    scanf("%d%d%d%d", &a, &b, &c, &d);

    if (a > b) { t = a; a = b; b = t; }
    if (a > c) { t = a; a = c; c = t; }
    if (a > d) { t = a; a = d; d = t; }
    // 此时 a 是最小的

    if (b > c) { t = b; b = c; c = t; }
    if (b > d) { t = b; b = d; d = t; }
    // 此时 b 是第二小的

    if (c > d) { t = c; c = d; d = t; }
    // 排序完成

    printf("排序结果: %d %d %d %d\n", a, b, c, d);
    return 0;
}

#include <stdio.h>
