int main() {
    double x, y, h;
    int in_circle = 0;

    printf("请输入点坐标(x,y): ");
    scanf("%lf,%lf", &x, &y);

    // 判断是否在四个圆中任意一个圆内
    // 点到圆心的距离平方 d^2 = (x-a)^2 + (y-b)^2，如果 d^2 <= r^2 (1^2=1)，则在圆内
    if ((pow(x-2, 2) + pow(y-2, 2) <= 1) || 
        (pow(x+2, 2) + pow(y-2, 2) <= 1) || 
        (pow(x+2, 2) + pow(y+2, 2) <= 1) || 
        (pow(x-2, 2) + pow(y+2, 2) <= 1)) {
        in_circle = 1;
    }

    if (in_circle) h = 10;
    else h = 0;

    printf("该点高度为: %.1f\n", h);
