double solution(double a, double b, double c, double d) {
    double x = 1.0, x0, f, f_prime;
    do {
        x0 = x;
        f = ((a * x0 + b) * x0 + c) * x0 + d;  // ax^3 + bx^2 + cx + d
        f_prime = (3 * a * x0 + 2 * b) * x0 + c; // 3ax^2 + 2bx + c
        x = x0 - f / f_prime;
    } while (fabs(x - x0) >= 1e-5);
    return x;
}

