#include <stdio.h>

#define STU 10
#define COURSE 5

void stu_avg(float score[STU][COURSE], float avg[STU]) {
    for (int i = 0; i < STU; i++) {
        float sum = 0;
        for (int j = 0; j < COURSE; j++) sum += score[i][j];
        avg[i] = sum / COURSE;
    }
}

void course_avg(float score[STU][COURSE], float avg[COURSE]) {
    for (int j = 0; j < COURSE; j++) {
        float sum = 0;
        for (int i = 0; i < STU; i++) sum += score[i][j];
        avg[j] = sum / STU;
    }
}

void find_max(float score[STU][COURSE]) {
    float max = score[0][0];
    int stu_idx = 0, course_idx = 0;
    for (int i = 0; i < STU; i++) {
        for (int j = 0; j < COURSE; j++) {
            if (score[i][j] > max) {
                max = score[i][j];
                stu_idx = i;
                course_idx = j;
            }
        }
    }
    printf("最高分: %.2f, 学生: %d, 课程: %d\n", max, stu_idx + 1, course_idx + 1);
}

float variance(float avg_stu[STU]) {
    float sum_sq = 0, sum = 0;
    for (int i = 0; i < STU; i++) {
        sum_sq += avg_stu[i] * avg_stu[i];
        sum += avg_stu[i];
    }
    return (sum_sq / STU) - (sum / STU) * (sum / STU);
}

int main() {
    float score[STU][COURSE], avg_s[STU], avg_c[COURSE];
    // 简化输入，实际运行需手动输入50个数据
