int hex_to_dec(char hex[]) {
    int len = strlen(hex);
    int dec = 0, base = 1;
    for (int i = len - 1; i >= 0; i--) {
        int val;
        if (isdigit(hex[i])) {
            val = hex[i] - '0';
        } else {
            val = toupper(hex[i]) - 'A' + 10;
        }
        dec += val * base;
        base *= 16;
    }
    return dec;
}

