#include <stdio.h>
#include <stdlib.h>

struct Student {
    long num;
    float score;
    struct Student *next;
};

// 假设a, b已经是升序排列的
struct Student* merge(struct Student *a, struct Student *b) {
    struct Student *head = NULL, *p = NULL;
    if (a == NULL) return b;
    if (b == NULL) return a;

    if (a->num < b->num) {
        head = a;
        a = a->next;
    } else {
        head = b;
        b = b->next;
    }
    p = head;

    while (a != NULL && b != NULL) {
        if (a->num < b->num) {
            p->next = a;
            a = a->next;
        } else {
            p->next = b;
            b = b->next;
        }
        p = p->next;
    }

    if (a != NULL) p->next = a;
    if (b != NULL) p->next = b;

    return head;
}
