                a = pa->next;
                temp = pa;
                pa = pa->next;
                free(temp);
            } else {
                prev->next = pa->next;
                temp = pa;
                pa = pa->next;
                free(temp);
            }
        } else {
            prev = pa;
            pa = pa->next;
        }
    }
    return a;
}
