struct Student {
    char num[10];
    char name[20];
    char sex;
    int age;
    struct Student *next;
};

struct Student* delete_by_age(struct Student *head, int age) {
    struct Student *p, *prev, *temp;

    while (head != NULL && head->age == age) {
        temp = head;
        head = head->next;
        free(temp);
    }

    if (head == NULL) return NULL;

    prev = head;
    p = head->next;

    while (p != NULL) {
        if (p->age == age) {
            prev->next = p->next;
            free(p);
            p = prev->next;
        } else {
            prev = p;
            p = p->next;
        }
    }
    return head;
}
