        exit(0);
    }
    // 打开文件B读取
    if ((fpB = fopen("B", "r")) == NULL) {
        printf("无法打开文件 B\n");
        exit(0);
    }
    // 打开文件C写入
    if ((fpC = fopen("C", "w")) == NULL) {
        printf("无法打开文件 C\n");
        exit(0);
    }

    i = 0;
    // 读取A的内容
    while ((ch = fgetc(fpA)) != EOF) {
        str[i++] = ch;
    }
    // 读取B的内容
    while ((ch = fgetc(fpB)) != EOF) {
        str[i++] = ch;
    }
    str[i] = '\0'; // 添加字符串结束符

    len = i;
    // 冒泡排序
    for (i = 0; i < len - 1; i++) {
        for (j = 0; j < len - 1 - i; j++) {
            if (str[j] > str[j + 1]) {
                temp = str[j];
                str[j] = str[j + 1];
                str[j + 1] = temp;
            }
        }
    }

    // 写入文件C
    for (i = 0; i < len; i++) {
        fputc(str[i], fpC);
    }

    printf("合并并排序完成，结果已保存到文件 C\n");

    fclose(fpA);
    fclose(fpB);
    fclose(fpC);
    return 0;
}
