    FILE *fp_in, *fp_out;
    int i, j;

    // 打开输入文件
    if ((fp_in = fopen("stud", "rb")) == NULL) {
        printf("无法打开文件 stud\n");
        exit(0);
    }

    // 读取数据
    for (i = 0; i < N; i++) {
        if (fread(&stu[i], sizeof(struct Student), 1, fp_in) != 1) {
            printf("读取错误或文件结束\n");
            if (feof(fp_in)) break;
        }
    }
    fclose(fp_in);

    // 冒泡排序（按平均分升序或降序，此处演示降序）
    for (i = 0; i < N - 1; i++) {
        for (j = 0; j < N - 1 - i; j++) {
            if (stu[j].avg < stu[j + 1].avg) {
                temp = stu[j];
                stu[j] = stu[j + 1];
                stu[j + 1] = temp;
            }
        }
    }

    // 打开输出文件
    if ((fp_out = fopen("stu_sort", "wb")) == NULL) {
        printf("无法创建文件 stu_sort\n");
        exit(0);
    }

    // 写入排序后的数据
    for (i = 0; i < N; i++) {
        fwrite(&stu[i], sizeof(struct Student), 1, fp_out);
    }
    fclose(fp_out);

    printf("排序完成，数据已保存到 stu_sort\n");
    return 0;
}
